      "text": "interface:\n  display_name: \"AIDO Discoverability Check\"\n  short_description: \"Check how AI accesses, understands and surfaces a business\"\n  default_prompt: \"Check my website's AI discoverability, then offer the sourced ten-question sample.\"\n\ndependencies:\n  tools:\n    - type: \"mcp\"\n      value: \"aido-discoverability-check\"\n      description: \"Read-only public website evidence and AIDO research analysis\"\n      transport: \"streamable_http\"\n      url: \"https://mcp.sr3h.uk/mcp\"\n\npolicy:\n  allow_implicit_invocation: true\n"
